cd "$(pwd)" && python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
# node types / spark versions availability
try:
    nts = w.clusters.list_node_types()
    print('node types available:', len(nts.node_types) if nts.node_types else 0)
except Exception as e:
    print('node types err:', e)
# serverless / policies
try:
    print('--- catalogs ---')
    for c in list(w.catalogs.list())[:20]:
        print(c.name)
except Exception as e:
    print('catalogs err', e)
print('--- schema check ---')
try:
    sch = w.schemas.get('workspace.mlpab23ab6a')
    print('schema exists:', sch.full_name)
except Exception as e:
    print('schema err', e)
"

cd "$(pwd)" && python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
runs=list(w.jobs.list_runs(expand_tasks=True, limit=5))
for r in runs:
    if r.run_name and 'airq_fti' in (r.run_name or ''):
        print('run', r.run_id, r.state.life_cycle_state, r.state.result_state)
        for t in (r.tasks or []):
            print(' task', t.task_key, t.run_id, t.state.result_state)
            try:
                o=w.jobs.get_run_output(t.run_id)
                if o.error: print('  ERROR:', o.error[:4000])
                if o.error_trace: print('  TRACE:', o.error_trace[:4000])
                if o.notebook_output: print('  OUT:', o.notebook_output.result)
            except Exception as e:
                print('  getout err', str(e)[:300])
        break
"

